import pygame
import random
import sys

W, H = 400, 600
GROUND = 520
GRAV = 0.45
FLAP = -7.5
BIRD_X, R = 80, 12


def main():
    pygame.init()
    screen = pygame.display.set_mode((W, H))
    pygame.display.set_caption("Flappy Bird")
    clock = pygame.time.Clock()
    font = pygame.font.SysFont(None, 40)
    small = pygame.font.SysFont(None, 26)

    def reset():
        return {"y": H // 2, "v": 0.0, "pipes": [], "score": 0,
                "spawn": 60, "over": False, "started": False}

    st = reset()

    def speed():
        return min(3.0 + st["score"] * 0.05, 6.0)

    def gap_size():
        return max(180 - st["score"] * 2, 110)

    def add_pipe():
        gap = gap_size()
        margin = 60
        top = random.randint(margin, GROUND - gap - margin)
        st["pipes"].append({"x": float(W), "top": top, "gap": gap,
                            "w": 60, "passed": False})

    running = True
    while running:
        for e in pygame.event.get():
            if e.type == pygame.QUIT:
                running = False
            elif e.type == pygame.KEYDOWN:
                if e.key in (pygame.K_SPACE, pygame.K_UP):
                    if st["over"]:
                        st = reset()
                    else:
                        st["started"] = True
                        st["v"] = FLAP
                elif e.key == pygame.K_ESCAPE:
                    running = False

        if st["started"] and not st["over"]:
            st["v"] += GRAV
            st["y"] += st["v"]
            if st["y"] - R < 0:
                st["y"] = R
                st["v"] = 0.0
            sp = speed()
            st["spawn"] -= 1
            if st["spawn"] <= 0:
                add_pipe()
                st["spawn"] = int(270 / sp)
            for p in st["pipes"]:
                p["x"] -= sp
            st["pipes"] = [p for p in st["pipes"] if p["x"] + p["w"] > -10]
            for p in st["pipes"]:
                if not p["passed"] and p["x"] + p["w"] < BIRD_X - R:
                    p["passed"] = True
                    st["score"] += 1
            if st["y"] + R >= GROUND:
                st["over"] = True
            else:
                for p in st["pipes"]:
                    if BIRD_X + R > p["x"] and BIRD_X - R < p["x"] + p["w"]:
                        if st["y"] - R < p["top"] or st["y"] + R > p["top"] + p["gap"]:
                            st["over"] = True
                            break

        screen.fill((113, 197, 207))
        pygame.draw.rect(screen, (222, 216, 149), (0, GROUND, W, H - GROUND))
        for p in st["pipes"]:
            pygame.draw.rect(screen, (111, 196, 69),
                             (int(p["x"]), 0, p["w"], int(p["top"])))
            pygame.draw.rect(screen, (111, 196, 69),
                             (int(p["x"]), int(p["top"] + p["gap"]), p["w"],
                              GROUND - int(p["top"] + p["gap"])))
        by = int(st["y"])
        pygame.draw.circle(screen, (255, 204, 0), (BIRD_X, by), R)
        pygame.draw.polygon(screen, (255, 140, 0),
                            [(BIRD_X, by), (BIRD_X + 12, by), (BIRD_X, by + 6)])
        pygame.draw.circle(screen, (30, 30, 30), (BIRD_X + 5, by - 4), 2)
        s = font.render(str(st["score"]), True, (255, 255, 255))
        screen.blit(s, (W // 2 - s.get_width() // 2, 20))
        if not st["started"]:
            t = small.render("Press SPACE to flap", True, (255, 255, 255))
            screen.blit(t, (W // 2 - t.get_width() // 2, H // 2 - 80))
        if st["over"]:
            t = font.render("Game Over! SPACE = retry", True, (255, 70, 70))
            screen.blit(t, (W // 2 - t.get_width() // 2, H // 2 - 30))
        pygame.display.flip()
        clock.tick(60)

    pygame.quit()
    sys.exit()


if __name__ == "__main__":
    main()
